def load_config() -> AppConfig:
    """Load and validate system configuration from environment variables."""
    return AppConfig()

class QueryRequest(BaseModel):
    query: str
    top_k: int = 5

def create_app():
    """Create and configure FastAPI application."""
    # Simulated FastAPI application
    app_routes = {
        "/query": "Handles user queries via RAGPipeline",
        "/index": "Ingests new documents into vector store",
        "/health": "Service health check endpoint"
    }
    return app_routes

def handle_query(request: QueryRequest) -> Dict[str, Any]:
    """Process query endpoint execution."""
    return pipeline.run(request.query)

def handle_index(request: IndexRequest) -> Dict[str, Any]:
    """Process document ingestion endpoint."""
    count = pipeline.retriever.add_documents(request.documents)
    return {"status": "success", "indexed_count": count}

def health_check() -> Dict[str, str]:
    """Health status check."""
    return {"status": "healthy", "service": config.app_name}

class RAGPipeline:
    """Manages question retrieval, prompt building, and response synthesis."""

    def __init__(
        self,
        retriever: Optional[SemanticRetriever] = None,
        config: Optional[PipelineConfig] = None
    ):
        self.retriever = retriever or SemanticRetriever()
        self.config = config or PipelineConfig()

    def format_prompt(self, query: str, context_chunks: List[Dict[str, Any]]) -> str:
        """Construct grounded prompt combining query and retrieved evidence."""
        context_text = "\n\n".join(
            f"[{i+1}] {chunk.get('text', '')}"
            for i, chunk in enumerate(context_chunks)
        )
        return (
            f"Use the following context to answer the question:\n"
            f"{context_text}\n\n"
            f"Question: {query}\n"
            f"Answer:"
        )

    def run(self, query: str) -> Dict[str, Any]:
        """Execute complete RAG workflow: retrieve, prompt, and synthesize."""
        docs = self.retriever.retrieve(query, top_k=self.config.max_retrieved_docs)
        prompt = self.format_prompt(query, docs)

        answer = f"Synthesized response for '{query}' based on {len(docs)} retrieved sources."
        return {
            "query": query,
            "answer": answer,
            "retrieved_documents": docs,
            "prompt_length": len(prompt)
        }

def format_prompt(self, query: str, context_chunks: List[Dict[str, Any]]) -> str:
    """Construct grounded prompt combining query and retrieved evidence."""
    context_text = "\n\n".join(
        f"[{i+1}] {chunk.get('text', '')}"
        for i, chunk in enumerate(context_chunks)
    )
    return (
        f"Use the following context to answer the question:\n"
        f"{context_text}\n\n"
        f"Question: {query}\n"
        f"Answer:"
    )

def add_documents(self, documents: List[Dict[str, Any]]) -> int:
    """Embed and insert new documents into vector store."""
    vectors = [self.encode_query(doc.get("text", "")) for doc in documents]
    self.vector_store.add_vectors(vectors, documents)
    self.cache.invalidate("query:*")
    return len(documents)

class RedisCache:
    """Redis-backed key-value cache for hot queries and query embeddings."""

    def __init__(self, config: Optional[CacheConfig] = None):
        self.config = config or CacheConfig()
        self.client = None
        self._in_memory_store = {}

    def get(self, key: str) -> Optional[Any]:
        """Fetch cached response or embedding vector."""
        if not self.config.enabled:
            return None
        return self._in_memory_store.get(key)

    def set(self, key: str, value: Any, ttl: Optional[int] = None) -> bool:
        """Store key-value pair in cache with expiration."""
        if not self.config.enabled:
            return False
        self._in_memory_store[key] = value
        return True

    def invalidate(self, pattern: str) -> int:
        """Invalidate keys matching specified pattern."""
        count = len(self._in_memory_store)
        self._in_memory_store.clear()
        return count

